<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { Cable, Plus, Radio, Trash2, ToggleLeft, ToggleRight, Pencil, PlugZap } from 'lucide-vue-next'
import PageHeader from '../components/PageHeader.vue'; import EmptyState from '../components/EmptyState.vue'; import AppDialog from '../components/AppDialog.vue'
import { useResourcesStore } from '../stores/resources'; import { useAppStore } from '../stores/app'; import { api } from '../api/client'; import type { Source, SourceTest } from '../types/api'
const store = useResourcesStore(); const app = useAppStore(); const editorOpen = ref(false); const editing = ref<Source | null>(null); const deleteTarget = ref<Source | null>(null); const testing = ref<number | null>(null); const testResult = ref<SourceTest | null>(null); const form = ref({ name:'', conversation_id:'', enabled:true, auto_extract:true, context_window:5, privacy_policy:'default' })
onMounted(() => store.loadSources())
function openCreate() { editing.value = null; form.value = { name:'', conversation_id:'', enabled:true, auto_extract:true, context_window:5, privacy_policy:'default' }; editorOpen.value = true }
function openEdit(source: Source) { editing.value = source; form.value = { name:source.name, conversation_id:source.conversation_id, enabled:source.enabled, auto_extract:source.auto_extract, context_window:source.context_window, privacy_policy:source.privacy_policy }; editorOpen.value = true }
async function save() { try { const saved = editing.value ? await api.updateSource(editing.value.id, { name:form.value.name, enabled:form.value.enabled, auto_extract:form.value.auto_extract, context_window:form.value.context_window, privacy_policy:form.value.privacy_policy }) : await api.createSource({ platform:'onebot', ...form.value }); if (editing.value) Object.assign(editing.value, saved); else store.sources.push(saved); editorOpen.value = false; app.toast('连接已保存') } catch (e) { app.toast(e instanceof Error ? e.message : '保存失败') } }
async function toggle(source: Source) { try { Object.assign(source, await api.updateSource(source.id, { enabled:!source.enabled })); app.toast(source.enabled ? '已启用消息源' : '已暂停消息源') } catch (e) { app.toast(e instanceof Error ? e.message : '更新失败') } }
async function test(source: Source) { testing.value = source.id; testResult.value = null; try { testResult.value = await api.testSource(source.id) } catch (e) { testResult.value = { ok:false, reachable:false, latency_ms:null, error_category:'request', message:e instanceof Error ? e.message : '测试失败' } } finally { testing.value = null } }
async function remove() { if (!deleteTarget.value) return; try { await api.deleteSource(deleteTarget.value.id); store.sources = store.sources.filter(s => s.id !== deleteTarget.value?.id); app.toast('消息源已移除'); deleteTarget.value = null } catch (e) { app.toast(e instanceof Error ? e.message : '移除失败') } }
</script>
<template><section class="page-content connections-page"><PageHeader eyebrow="数据入口" title="连接" description="管理 CampusCue 读取校园消息的入口。"><button class="button button-primary" @click="openCreate"><Plus :size="16" />添加连接</button></PageHeader><section class="connection-grid" v-if="store.sources.length"><article v-for="source in store.sources" :key="source.id" class="panel connection-card"><div class="connection-card-top"><div class="source-icon"><Radio :size="19" /></div><div><h3>{{ source.name || source.conversation_id }}</h3><p>{{ source.platform }} · {{ source.conversation_id }}</p></div><span class="status-badge" :class="source.enabled ? 'success' : 'muted'">{{ source.enabled ? '已启用' : '已暂停' }}</span></div><div class="connection-meta"><span>自动提取任务 <strong>{{ source.auto_extract ? '开启' : '关闭' }}</strong></span><span>上下文窗口 <strong>{{ source.context_window }} 条</strong></span><span v-if="testResult && testResult.ok" class="test-success">自检通过 · {{ testResult.latency_ms?.toFixed(0) || '—' }} ms</span><span v-else-if="testResult" class="test-fail">自检失败 · {{ testResult.message }}</span></div><div class="card-actions"><button class="button button-secondary" :disabled="testing === source.id" @click="test(source)"><PlugZap :size="16" />{{ testing === source.id ? '测试中…' : '测试连接' }}</button><button class="icon-button" :aria-label="`编辑${source.name || source.conversation_id}`" @click="openEdit(source)"><Pencil :size="16" /></button><button class="icon-button" :aria-label="source.enabled ? '暂停连接' : '启用连接'" @click="toggle(source)"><component :is="source.enabled ? ToggleRight : ToggleLeft" :size="18" /></button><button class="icon-button danger-button" :aria-label="`移除${source.name || source.conversation_id}`" @click="deleteTarget = source"><Trash2 :size="17" /></button></div></article></section><section v-else class="connection-empty"><EmptyState variant="connection" title="还没有连接" description="添加一个消息源后，CampusCue 才能从校园消息中提取事务。"><button class="text-link button-reset" @click="openCreate">添加消息源 <Plus :size="14" /></button></EmptyState></section><AppDialog :open="editorOpen" :title="editing ? '编辑消息源' : '添加消息源'" description="配置会话入口与隐私策略" @close="editorOpen = false"><form class="task-editor" @submit.prevent="save"><label>显示名称<input v-model="form.name" placeholder="例如：高数课程群" /></label><label v-if="!editing">会话标识<input v-model="form.conversation_id" required placeholder="会话 ID" /></label><label>上下文窗口<input v-model.number="form.context_window" type="number" min="1" /></label><label>隐私策略<select v-model="form.privacy_policy"><option value="default">默认</option><option value="no_retention">不保留原文</option></select></label><label class="check-line"><input v-model="form.auto_extract" type="checkbox" />自动提取任务</label><label class="check-line"><input v-model="form.enabled" type="checkbox" />启用消息源</label><div class="form-actions"><button type="button" class="button button-secondary" @click="editorOpen = false">取消</button><button class="button button-primary">保存连接</button></div></form></AppDialog><AppDialog :open="Boolean(deleteTarget)" title="移除消息源" description="软删除会保留已有任务来源关系。" @close="deleteTarget = null"><p class="dialog-copy">确定移除“{{ deleteTarget?.name || deleteTarget?.conversation_id }}”吗？</p><template #footer><button class="button button-secondary" @click="deleteTarget = null">取消</button><button class="button button-danger" @click="remove">移除</button></template></AppDialog></section></template>
